pres.map((pre, i) => {
  const svg = pre.querySelector('svg');
  if (!svg) return {i, rendered: false, text: pre.textContent.slice(0, 60)};
  const edges = [...svg.querySelectorAll('path[data-id]')].filter(p => !p.closest('marker'));
  const arrows = edges.filter(p => p.getAttribute('marker-start') || p.getAttribute('marker-end')).map(p => {
    const id = p.getAttribute('data-id');
    const dir = p.getAttribute('marker-start') ? 'start' : 'end';
    const len = p.getTotalLength();
    const a = p.getPointAtLength(0), b = p.getPointAtLength(len);
    // 矢じりのある端の y と、もう一方の端の y を比べて向きを出す
    const head = dir === 'start' ? a : b, tail = dir === 'start' ? b : a;
    return id.replace(/_\d+$/, '') + ':' + (head.y < tail.y - 2 ? '上' : head.y > tail.y + 2 ? '下' : '横');
  });
  const clusters = [...svg.querySelectorAll('g.cluster')].map(c => {
    const r = c.querySelector('rect'); return [c.id.replace(/^.*?-(U\w+).*$/, '$1'), Math.round(r.getBoundingClientRect().top)];
  }).sort((x, y) => x[1] - y[1]).map(x => x[0]);
  return {i, rendered: true, width: Math.round(svg.getBoundingClientRect().width), clusters: clusters.join('>'), arrows: arrows.join(' ')};
});

